particulares.source:
---
import Arrow from '../components/Arrow.astro';
import Layout from '../layouts/Layout.astro';
import PageHero from '../components/PageHero.astro';
import ServiceBlock from '../components/ServiceBlock.astro';
import ContactCta from '../components/ContactCta.astro';
import { href } from '../data/site';
---
<Layout current="particulares/" title="Servicios jurídicos para particulares | Jaime Valiente" description="Asuntos civiles, de familia y sucesiones y penales. Propuesta de servicios para particulares.">
<PageHero eyebrow="Particulares" title="Servicios jurídicos para particulares." description="Asesoramiento en asuntos civiles, de familia y sucesiones y penales. Conoce las áreas de actuación y contacta con el despacho para plantear tu situación." />
<div class="shell area-layout"><nav class="area-nav" aria-label="Áreas para particulares"><p>En esta página</p><a href="#civil">Derecho civil</a><a href="#familia">Familia y sucesiones</a><a href="#penal">Derecho penal</a></nav><div>
<ServiceBlock id="civil" number="01" title="Derecho civil" intro="Asesoramiento en contratos y obligaciones, responsabilidad civil e indemnizaciones y procedimientos judiciales civiles." items={['Contratos y obligaciones','Responsabilidad civil e indemnizaciones','Procedimientos judiciales civiles']}><p class="related-link">Si tu consulta se refiere a una cantidad pendiente de pago, consulta <a href={href('reclamaciones/')}>Reclamaciones de cantidad</a>.</p></ServiceBlock>
<section id="familia" class="service-block" tabindex="-1" aria-labelledby="familia-title"><div class="service-title"><span class="section-number">02</span><h2 id="familia-title">Familia<br />y sucesiones</h2></div><div class="service-body"><p class="service-intro">Asesoramiento en asuntos familiares y sucesorios. Consulta el alcance de cada servicio para plantear tu situación.</p><h3>Familia</h3><ul class="service-list"><li>Divorcios y separaciones</li><li>Guarda y custodia</li><li>Pensiones de alimentos</li><li>Liquidación del régimen económico matrimonial</li></ul><h3>Herencias y sucesiones</h3><ul class="service-list"><li>Herencias y sucesiones</li><li>Testamentos y cuadernos particionales</li><li>Adjudicación y reparto de bienes hereditarios</li><li>Conflictos entre herederos</li></ul><a class="text-link" href={href('contacto/')}>Consultar sobre familia o herencias <Arrow /></a></div></section>
<ServiceBlock id="penal" number="03" title="Derecho penal" intro="Asistencia y defensa penal y acusación particular. Contacta para consultar la atención de tu asunto." items={['Asistencia y defensa penal','Acusación particular','Denuncias y querellas','Delitos contra las personas y el patrimonio']} />
<p class="small-note">Para iniciar el contacto, indica brevemente el área de tu consulta y cómo contactar contigo. Si hay una notificación o una fecha relevante, comunícalo al despacho. No envíes expedientes ni datos de terceros por el primer mensaje.</p></div></div>
<ContactCta title="Plantea tu consulta." action="Solicitar consulta" />
</Layout>

empresas.source:
---
import Arrow from '../components/Arrow.astro';
import Layout from '../layouts/Layout.astro';
import PageHero from '../components/PageHero.astro';
import ServiceBlock from '../components/ServiceBlock.astro';
import ContactCta from '../components/ContactCta.astro';
import { href } from '../data/site';
---
<Layout current="empresas/" title="Asesoramiento para empresas y autónomos | Jaime Valiente" description="Asesoramiento jurídico y mercantil, laboral, contable y fiscal para empresas y autónomos. Demo para revisión.">
<PageHero eyebrow="Empresas y autónomos" title="Asesoramiento para empresas y autónomos." description="Servicios jurídicos y mercantiles, laborales, contables y fiscales para empresas y autónomos. Consulta el ámbito de cada área y contacta para concretar las necesidades de tu actividad." action="Consultar sobre mi empresa" dark />
<div class="shell area-layout"><nav class="area-nav" aria-label="Áreas para empresas"><p>En esta página</p><a href="#mercantil">Jurídico y mercantil</a><a href="#laboral">Laboral</a><a href="#contable-fiscal">Contable y fiscal</a></nav><div>
<ServiceBlock id="mercantil" number="01" title="Jurídico y mercantil" intro="Asesoramiento jurídico a sociedades y empresas, desde su organización hasta sus contratos y operaciones empresariales." items={['Asesoramiento jurídico a sociedades y empresas','Constitución y organización de sociedades','Preparación y redacción de actas','Convocatoria y celebración de juntas de socios','Redacción y revisión de contratos mercantiles','Asesoramiento en acuerdos y operaciones empresariales']} action="Consultar sobre mi empresa" />
<ServiceBlock id="laboral" number="02" title="Asesoramiento laboral" intro="Asesoramiento laboral dirigido a empresas y autónomos. Consulta el alcance de la atención que necesita tu actividad." items={['Elaboración y gestión de nóminas','Gestión de seguros sociales','Contratación laboral','Procedimientos laborales','Despidos, sanciones y reclamaciones laborales']} action="Consultar sobre el área laboral" />
<ServiceBlock id="contable-fiscal" number="03" title="Contable y fiscal" intro="Asesoramiento contable y fiscal a empresas y autónomos, con atención a la contabilidad, los impuestos y los procedimientos tributarios." items={['Llevanza y supervisión de contabilidades','Organización y control contable','Elaboración de informes contables','Asesoramiento fiscal a empresas y autónomos','Preparación y presentación de impuestos','Planificación fiscal','Atención a requerimientos y procedimientos tributarios']} action="Consultar sobre contabilidad o fiscalidad" />
<div class="related-card"><p class="eyebrow">Cantidades pendientes de cobro</p><h3>Reclamación de deudas</h3><p>Si necesitas consultar una deuda pendiente de cobro, accede al área de reclamaciones para conocer los servicios de negociación, reclamación judicial y ejecución.</p><a class="text-link" href={href('reclamaciones/')}>Ir a Reclamaciones <Arrow /></a></div></div></div>
<ContactCta title="Cuéntanos qué necesita tu empresa." description="Contacta con el despacho para concretar el área de asesoramiento y las condiciones de atención." action="Consultar sobre mi empresa" />
</Layout>

reclamaciones.source:
---
import Arrow from '../components/Arrow.astro';
import Layout from '../layouts/Layout.astro';
import PageHero from '../components/PageHero.astro';
import ServiceBlock from '../components/ServiceBlock.astro';
import ContactCta from '../components/ContactCta.astro';
import { href } from '../data/site';
---
<Layout current="reclamaciones/" title="Reclamación de deudas | Jaime Valiente Abogado" description="Deudas, procedimientos monitorios, negociación y ejecución de resoluciones judiciales. Demo de diseño.">
<PageHero eyebrow="Reclamaciones" title="Reclamación de deudas y ejecución de resoluciones." description="Servicios de reclamación judicial de deudas, procedimientos monitorios, ejecución de resoluciones judiciales y negociación para la resolución extrajudicial de conflictos. Una vía de consulta para particulares y empresas con cantidades pendientes de cobro." action="Consultar una reclamación" />
<div class="shell area-layout"><nav class="area-nav" aria-label="Ámbitos de reclamación"><p>En esta página</p><a href="#deuda">Deudas</a><a href="#negociacion">Negociación</a><a href="#judicial">Reclamación judicial</a><a href="#ejecucion">Ejecución</a></nav><div>
<ServiceBlock id="deuda" number="01" title="Deudas pendientes" intro="Si necesitas consultar una deuda, contacta con el despacho para exponer brevemente su origen y tu situación. La vía de actuación deberá valorarse según el asunto." items={[]} action="Consultar una deuda" />
<ServiceBlock id="negociacion" number="02" title="Negociación extrajudicial" intro="Asesoramiento en negociación y resolución extrajudicial de conflictos. Contacta con el despacho para consultar su encaje en tu asunto." items={[]} action="Consultar sobre negociación" />
<ServiceBlock id="judicial" number="03" title="Reclamación judicial y monitorios" intro="Asesoramiento en reclamaciones judiciales de deudas y procedimientos monitorios. Contacta para consultar qué atención puede ofrecerte el despacho." items={[]} action="Consultar una reclamación" />
<ServiceBlock id="ejecucion" number="04" title="Ejecución de resoluciones" intro="Si tu consulta se relaciona con el cumplimiento de una resolución judicial, explica brevemente qué necesitas al solicitar la consulta; la actuación dependerá de la valoración del asunto." items={[]} action="Consultar sobre ejecución" />
<p class="small-note">Esta información no determina si una reclamación es viable ni qué procedimiento corresponde. El primer contacto no supone la aceptación del encargo ni garantiza un resultado.</p><div class="related-grid"><article class="related-card"><h3>Otros asuntos civiles</h3><p>Responsabilidad civil, indemnizaciones y otros asuntos personales.</p><a class="text-link" href={href('particulares/#civil')}>Ver Derecho civil <Arrow /></a></article><article class="related-card"><h3>Reclamaciones laborales</h3><p>Despidos, sanciones y reclamaciones laborales de empresas y autónomos.</p><a class="text-link" href={href('empresas/#laboral')}>Ver el área laboral <Arrow /></a></article></div></div></div>
<ContactCta title="Consulta tu reclamación." action="Contactar con el despacho" />
</Layout>
